require_once dirname(__DIR__).'/includes/shop_storefront.php';
require_once dirname(__DIR__).'/includes/shop_program_quick_checkout.php';
require_once dirname(__DIR__).'/includes/auth_rate_limit.php';

function quickProgramH(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function quickProgramMoney(int $minor,string $currency):string{return number_format($minor/100,2,',',' ').' '.quickProgramH($currency);}

$productId=(int)($_POST['product_id']??$_GET['product_id']??0);$variantId=(int)($_POST['variant_id']??$_GET['variant_id']??0);
$product=shopStorefrontProductDetail($pdo,$productId);$variant=null;$offer=false;
if($product!==null&&shopProductRequiresAthlete($pdo,$productId))foreach($product['variants']as$candidate)if((int)$candidate['variant_id']===$variantId){$state=clubProgramVariantSaleState($pdo,$variantId);if($state['saleable']){$variant=$candidate;$offer=$state['offer'];}break;}
if($product===null||$variant===null||!is_array($offer)){http_response_code(404);exit('Kroužek není dostupný pro rychlou přihlášku.');}
if(isset($_SESSION['verejny_uzivatel_id'])){header('Location: produkt.php?id='.$productId,true,303);exit;}
$terms=athleteRegistrationCurrentTerms($pdo);$programTerms=clubProgramTermsEffective($pdo,(int)$offer['program_id'],(int)$offer['id']);
if(!clubProgramTermsComplete($programTerms)){http_response_code(409);exit('Kroužek nemá schválené podmínky.');}
$keyName='shop_quick_program_'.$variantId;if(!isset($_SESSION[$keyName])||!is_array($_SESSION[$keyName]))$_SESSION[$keyName]=['idempotency_key'=>bin2hex(random_bytes(16)),'access_token'=>bin2hex(random_bytes(32))];
$errors=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku a zkuste to znovu.';
    else try{
        $email=strtolower(trim((string)($_POST['email']??'')));if(!auth_rate_limit_reserve_attempt($pdo,'quick_program_checkout',$email,auth_rate_limit_request_ip()))throw new ShopCheckoutException('Příliš mnoho pokusů. Zkuste přihlášku dokončit později.');
        $keys=$_SESSION[$keyName];$order=shopProgramQuickCheckoutPlace($pdo,$variantId,$_POST,is_array($_POST['term_version']??null)?$_POST['term_version']:[],(string)$keys['idempotency_key'],(string)$keys['access_token'],shopBankSettingsEffective($pdo));
        unset($_SESSION[$keyName]);header('Location: objednavka.php?code='.rawurlencode((string)$order['public_code']).'&access='.rawurlencode((string)$keys['access_token']),true,303);exit;
    }catch(InvalidArgumentException|ShopCheckoutException|ShopProgramQuickCheckoutException|AthleteRegistrationException|PersonSensitiveException $exception){$errors[]=$exception->getMessage();}
    catch(Throwable $exception){error_log('booking/rychla_prihlaska.php: '.get_class($exception));$errors[]='Přihlášku se nepodařilo bezpečně uložit. Zkuste to znovu.';}
}
$value=static fn(string$key,string$default=''):string=>quickProgramH($_POST[$key]??$default);
?>
