<script>(()=>{const input=document.getElementById('quick-birth-date');const box=document.getElementById('quick-age-warning');const text=box?.querySelector('span');const from=<?=json_encode($offer['birth_year_from']!==null?(int)$offer['birth_year_from']:null)?>;const to=<?=json_encode($offer['birth_year_to']!==null?(int)$offer['birth_year_to']:null)?>;const update=()=>{if(!input||!box||!text||!input.value||(!from&&!to)){box?.classList.add('d-none');return;}const year=Number(input.value.slice(0,4));const mismatch=(from!==null&&year<from)||(to!==null&&year>to);box.classList.toggle('d-none',!mismatch);text.textContent=mismatch?`Ročník ${year} je mimo doporučené rozpětí${from!==null&&to!==null?` ${from}–${to}`:''}.`:'';};input?.addEventListener('change',update);update();})();</script></body></html>
